"""Renderers: contract -> the exact bytes of every generated file.

A renderer is a pure function of the :class:`~leviath_codegen.model.Contract`, so
the same contract always produces the same bytes.  That is what makes the second
invocation a no-op.  No timestamp, no random value, no filesystem read: the only
inputs are the contract and the module constants.

Each renderer returns an :class:`EmittedFile`: the path, the text and the
``anchors`` — the symbol names it defined, with their line numbers.  The anchors
become the source map, so every generated symbol points back at the contract line
that produced it.
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field
from typing import Dict, Iterable, List, Mapping, Optional, Sequence, Tuple

from graphql.language.ast import NonNullTypeNode

from .model import (
    CONTRACT_SDL_NAME,
    PYTHON_BUILTIN_SCALARS,
    PYTHON_CUSTOM_SCALARS,
    TYPESCRIPT_SCALARS,
    Contract,
    Operation,
    Selection,
    VERSION,
    pascal,
    scalar_mapping,
    snake,
)

#: The line every generated file carries, so an edited file is obvious.
BANNER_LINE = "generated by leviath_codegen — DO NOT EDIT; edit the contract instead"

#: Root operation types: covered by the generated operation clients, not by the
#: generated type stubs (a client method is a root field's typed shape).
ROOT_TYPE_NAMES = ("Query", "Mutation", "Subscription")

MANIFEST_FORMAT = "leviath-codegen-manifest/v1"
SOURCEMAP_FORMAT = "leviath-codegen-sourcemap/v1"


def is_identifier(name: str) -> bool:
    """True when ``name`` can be written as an identifier in both languages."""
    if not name or name[0].isdigit():
        return False
    return all(char.isalnum() or char == "_" for char in name)


def _assert_identifier(name: str, what: str) -> None:
    if not is_identifier(name):
        from .model import ContractDrift

        raise ContractDrift(f"{what} {name!r} is not a valid identifier; cannot generate")


@dataclass(frozen=True)
class EmittedFile:
    """One generated file: its path, its bytes and its symbol anchors."""

    path: str
    text: str
    anchors: Tuple[Tuple[str, int], ...] = ()
    #: True when the file is seeded once and then owned by the developer.
    handwritten: bool = False


@dataclass
class _Out:
    """A line accumulator that records where each symbol was written."""

    lines: List[str] = field(default_factory=list)
    anchors: List[Tuple[str, int]] = field(default_factory=list)

    def add(self, line: str = "", anchor: Optional[str] = None) -> None:
        self.lines.append(line)
        if anchor is not None:
            self.anchors.append((anchor, len(self.lines)))

    def extend(self, lines: Iterable[str]) -> None:
        for line in lines:
            self.add(line)

    def text(self) -> str:
        return "\n".join(self.lines).rstrip("\n") + "\n"


# ---------------------------------------------------------------------------
# Type expressions.
# ---------------------------------------------------------------------------


def _node(value) -> str:
    return str(value)


def python_annotation(
    graphql_type: str, contract: Contract, defined: Optional[Iterable[str]] = None
) -> str:
    """The Python annotation for a GraphQL type.

    ``defined`` is the set of names already emitted above this line.  A name that
    is *not* yet defined is quoted, so a forward reference stays legal both at
    runtime (the generated module uses ``from __future__ import annotations``) and
    for mypy.  ``None`` means "quote nothing".
    """
    from graphql import parse_type

    node = parse_type(graphql_type)
    scope = None if defined is None else set(defined)
    return _py_nullable(node, contract, scope)


def _py_nullable(node, contract: Contract, defined: Optional[set]) -> str:
    if isinstance(node, NonNullTypeNode):
        return _py_inner(node.type, contract, defined)
    return f"Optional[{_py_inner(node, contract, defined)}]"


def _py_inner(node, contract: Contract, defined: Optional[set]) -> str:
    kind = type(node).__name__
    if kind == "ListTypeNode":
        return f"Sequence[{_py_nullable(node.type, contract, defined)}]"
    if kind == "NonNullTypeNode":
        return _py_inner(node.type, contract, defined)
    return python_base(node.name.value, contract, defined)


def python_base(name: str, contract: Contract, defined: Optional[set] = None) -> str:
    """The Python name for one named GraphQL type, quoted when not yet defined."""
    if name in PYTHON_BUILTIN_SCALARS:
        return PYTHON_BUILTIN_SCALARS[name][1]
    if name in PYTHON_CUSTOM_SCALARS:
        return PYTHON_CUSTOM_SCALARS[name]
    generated = _composite_name(name, contract, python=True)
    if defined is not None and generated not in defined:
        return f'"{generated}"'
    return generated


def _composite_name(name: str, contract: Contract, *, python: bool) -> str:
    """The generated name for an object, interface or union type."""
    schema = contract.schema
    type_ = schema.type_map.get(name)
    if type_ is None:
        return name
    if _is_union(type_):
        return name
    if _is_interface(type_):
        union = f"{name}Union"
        if any(port == name for port, _ in contract.port_implementations):
            return union
        return name
    return name


def _is_union(type_) -> bool:
    return type(type_).__name__ == "GraphQLUnionType"


def _is_interface(type_) -> bool:
    return type(type_).__name__ == "GraphQLInterfaceType"


def typescript_annotation(graphql_type: str, contract: Contract) -> str:
    """The TypeScript annotation for a GraphQL type."""
    from graphql import parse_type

    node = parse_type(graphql_type)
    return _ts_nullable(node, contract)


def _ts_nullable(node, contract: Contract) -> str:
    if isinstance(node, NonNullTypeNode):
        return _ts_inner(node.type, contract)
    return f"Maybe<{_ts_inner(node, contract)}>"


def _ts_inner(node, contract: Contract) -> str:
    kind = type(node).__name__
    if kind == "ListTypeNode":
        return f"ReadonlyArray<{_ts_nullable(node.type, contract)}>"
    if kind == "NonNullTypeNode":
        return _ts_inner(node.type, contract)
    return typescript_base(node.name.value, contract)


def typescript_base(name: str, contract: Contract) -> str:
    if name in TYPESCRIPT_SCALARS:
        return TYPESCRIPT_SCALARS[name]
    return _composite_name(name, contract, python=False)


def _python_used_custom(contract: Contract) -> List[str]:
    """Custom scalar aliases the generated Python stubs must import.

    Every named type the stubs mention is inspected, so a scalar used only by a
    field of a referenced type is still imported.  ``PortValue`` is always
    imported, because the envelope helpers name it.
    """
    used = {"PortValue"}
    for name in _named_types_in_use(contract):
        if name in PYTHON_CUSTOM_SCALARS:
            used.add(PYTHON_CUSTOM_SCALARS[name])
    return sorted(used)


def _typescript_used_scalars(contract: Contract) -> List[str]:
    """Named TypeScript scalar aliases the generated stubs must import."""
    used = set()
    for name in _named_types_in_use(contract):
        mapped = TYPESCRIPT_SCALARS.get(name)
        if mapped is not None:
            used.add(mapped)
    return sorted(used)


def _named_types_in_use(contract: Contract) -> List[str]:
    """Every named type the generated stubs actually mention, plus variables."""
    from graphql import is_object_type, is_enum_type

    names: List[str] = []
    for name, type_ in contract.schema.type_map.items():
        if name.startswith("__") or name in ROOT_TYPE_NAMES:
            continue
        if is_object_type(type_) or _is_union(type_) or _is_interface(type_) or is_enum_type(type_):
            names.append(name)
            if is_object_type(type_) or _is_interface(type_):
                for field in type_.fields.values():
                    names.append(_unwrap(field.type))
    for operation in contract.operations:
        for variable in operation.variables:
            names.append(_unwrap_str(variable.graphql_type))
        for selection in _walk(operation.selection):
            names.append(selection.named_type)
    return names


def _unwrap(graphql_type) -> str:
    while hasattr(graphql_type, "of_type"):
        graphql_type = graphql_type.of_type
    return graphql_type.name


def _walk(selection: Selection) -> List[Selection]:
    out = [selection]
    for child in selection.children:
        out.extend(_walk(child))
    for fragment in selection.fragments:
        for child in fragment.children:
            out.extend(_walk(child))
    return out


# ---------------------------------------------------------------------------
# Contract documents.
# ---------------------------------------------------------------------------


def render_schema_sdl(contract: Contract) -> EmittedFile:
    """The canonical SDL: the accepted contract in its printed form.

    The bytes are exactly ``contract.printed_sdl``.  So this file's own SHA-256
    **is** the accepted fingerprint: "the generated SDL is the accepted contract"
    is a hash identity, not a resemblance.  There is no banner here on purpose —
    a comment would change the bytes and hide that identity.
    """
    return EmittedFile("contract/schema.graphql", contract.printed_sdl)


def render_operations_sdl(contract: Contract) -> EmittedFile:
    """Every operation document, in contract root-field order."""
    out = _Out()
    out.add(f"# {BANNER_LINE}")
    out.add(f"# contract fingerprint: {contract.fingerprint}")
    for operation in contract.operations:
        out.add("")
        out.add(f"# {operation.kind} {operation.name} -> {operation.root_field}")
        for line in operation.document.splitlines():
            out.add(line, anchor=operation.root_field if line.startswith(operation.kind) else None)
    return EmittedFile("contract/operations.graphql", out.text(), tuple(out.anchors))


# ---------------------------------------------------------------------------
# Python.
# ---------------------------------------------------------------------------


def render_python_scalars(contract: Contract) -> EmittedFile:
    out = _Out()
    out.add('"""Generated scalar mappings. DO NOT EDIT."""')
    out.add("")
    out.add(f"# {BANNER_LINE}")
    out.add("")
    out.add("from __future__ import annotations")
    out.add("")
    out.add("from typing import Final, Mapping, Protocol, TypeAlias")
    out.add("")
    for name in sorted(PYTHON_CUSTOM_SCALARS):
        if name in contract.scalars and name not in ("PortValue", "Confidential"):
            out.add(f"#: GraphQL `{name}` is carried as this type on the wire.")
            out.add(f"{name}: TypeAlias = str")
    out.add("")
    out.add("")
    out.add("class Confidential(Protocol):")
    out.add('    """Opaque sensitive value (contract R6).')
    out.add("")
    out.add("    The concrete value comes from the runtime confirmation gate (GQL-06).")
    out.add("    This generated alias never constructs, unwraps or serialises a secret;")
    out.add("    a directive declares the gate and authority is the principal plus the")
    out.add("    exact approved intent.")
    out.add('    """')
    out.add("")
    out.add("")
    out.add("#: Transport envelope for a domain port value (contract R2).")
    out.add("PortValue: TypeAlias = Mapping[str, object]")
    out.add("")
    out.add("")
    out.add("#: GraphQL scalar name -> the Python type the generated stubs use.")
    out.add("SCALAR_MAPPINGS: Final[Mapping[str, str]] = {")
    for name, row in sorted(scalar_mapping(contract).items()):
        out.add(f'    "{name}": "{row["python"]}",')
    out.add("}")
    return EmittedFile("python/leviath_generated/scalars.py", out.text(), tuple(out.anchors))


def _python_enum_lines(out: _Out, contract: Contract) -> List[str]:
    from graphql import is_enum_type

    emitted: List[str] = []
    for name, type_ in contract.schema.type_map.items():
        if name.startswith("__") or not is_enum_type(type_):
            continue
        _assert_identifier(name, "enum type")
        out.add("")
        out.add("")
        out.add(f"class {name}(enum.Enum):", anchor=name)
        for value in type_.values:
            _assert_identifier(value, f"enum value of {name}")
            out.add(f'    {value} = "{value}"', anchor=f"{name}.{value}")
        emitted.append(name)
    return emitted


def _python_object_order(contract: Contract) -> List[str]:
    """Object type names in dependency order, deterministically.

    A ``TypedDict`` that names another one is annotated in the contract order, so
    emitting definitions in dependency order keeps most annotations unquoted.
    Kahn's algorithm with a sorted tie-break keeps the order stable, which matters:
    an unstable order would make the second invocation differ from the first.
    """
    from graphql import is_object_type

    objects = {
        name: type_
        for name, type_ in contract.schema.type_map.items()
        if not name.startswith("__") and name not in ROOT_TYPE_NAMES and is_object_type(type_)
    }
    names = set(objects)
    deps: Dict[str, set] = {}
    for name, type_ in objects.items():
        references = {_unwrap(field.type) for field in type_.fields.values()}
        deps[name] = (references & names) - {name}

    ordered: List[str] = []
    remaining = dict(deps)
    while remaining:
        ready = sorted(name for name, needs in remaining.items() if not (needs - set(ordered)))
        if not ready:  # a cycle: break it deterministically, quoting the back edge
            ready = [sorted(remaining)[0]]
        for name in ready:
            ordered.append(name)
            remaining.pop(name, None)
    return ordered


def _python_port_protocols(out: _Out, contract: Contract) -> List[str]:
    from graphql import is_interface_type

    ports: List[str] = []
    for name, type_ in contract.schema.type_map.items():
        if name.startswith("__") or not is_interface_type(type_):
            continue
        _assert_identifier(name, "interface type")
        defined = set(ports)
        out.add("")
        out.add("")
        out.add(f"class {name}(Protocol):", anchor=name)
        out.add('    """Domain port (contract R1): `*Input`/`*Output` is port direction.')
        out.add("")
        out.add("    A port is never a GraphQL argument type; the value travels inside the")
        out.add('    generated `PortValue` envelope (contract R2).')
        out.add('    """')
        for field_name, field in type_.fields.items():
            out.add("")
            out.add("    @property")
            out.add(
                "    def "
                f"{field_name}(self) -> {python_annotation(str(field.type), contract, defined)}: ...",
                anchor=f"{name}.{field_name}",
            )
        ports.append(name)
    return ports


def _python_objects(out: _Out, contract: Contract) -> List[str]:
    emitted: List[str] = []
    for name in _python_object_order(contract):
        type_ = contract.schema.type_map[name]
        _assert_identifier(name, "object type")
        defined = set(emitted) | set(_python_enum_names(contract)) | {"WorkflowStepInput", "WorkflowStepOutput"}
        out.add("")
        out.add("")
        out.add(f"{name} = TypedDict(", anchor=name)
        out.add(f'    "{name}",')
        out.add("    {")
        out.add(f'        "__typename": Literal["{name}"],')
        for field_name, field in type_.fields.items():
            _assert_identifier(field_name, f"field of {name}")
            out.add(
                f'        "{field_name}": {python_annotation(str(field.type), contract, defined)},',
                anchor=f"{name}.{field_name}",
            )
        out.add("    },")
        out.add(")")
        emitted.append(name)
    return emitted


def _python_enum_names(contract: Contract) -> List[str]:
    from graphql import is_enum_type

    return sorted(
        name
        for name, type_ in contract.schema.type_map.items()
        if not name.startswith("__") and is_enum_type(type_)
    )


def _python_unions(out: _Out, contract: Contract) -> List[str]:
    from graphql import is_union_type

    emitted: List[str] = []
    for name, type_ in contract.schema.type_map.items():
        if name.startswith("__") or not is_union_type(type_):
            continue
        members = " | ".join(member.name for member in type_.types)
        out.add("")
        out.add("")
        out.add(f"{name}: TypeAlias = Union[{members}]", anchor=name)
        emitted.append(name)
    for port, implementations in _ports_with_implementations(contract):
        out.add("")
        out.add("")
        out.add(
            f"{port}Union: TypeAlias = Union["
            + ", ".join(implementations)
            + "]",
            anchor=f"{port}Union",
        )
        emitted.append(f"{port}Union")
    return emitted


def _ports_with_implementations(contract: Contract) -> List[Tuple[str, List[str]]]:
    order: List[str] = []
    grouped: Dict[str, List[str]] = {}
    for port, implementation in contract.port_implementations:
        if port not in grouped:
            grouped[port] = []
            order.append(port)
        grouped[port].append(implementation)
    return [(port, grouped[port]) for port in order]


def render_python_interfaces(contract: Contract) -> EmittedFile:
    out = _Out()
    out.add('"""Generated typed interfaces and scalar mappings. DO NOT EDIT."""')
    out.add("")
    out.add(f"# {BANNER_LINE}")
    out.add(f"# contract fingerprint: {contract.fingerprint}")
    out.add("")
    out.add("from __future__ import annotations")
    out.add("")
    out.add("import enum")
    out.add(
        "from typing import ("
    )
    out.add("    Final,")
    out.add("    Literal,")
    out.add("    Mapping,")
    out.add("    Optional,")
    out.add("    Protocol,")
    out.add("    Sequence,")
    out.add("    TypeAlias,")
    out.add("    TypedDict,")
    out.add("    Union,")
    out.add(")")
    used_custom = _python_used_custom(contract)
    if used_custom:
        out.add("")
        out.add("from .scalars import " + ", ".join(used_custom))

    _python_enum_lines(out, contract)
    _python_port_protocols(out, contract)
    _python_objects(out, contract)
    _python_unions(out, contract)

    ports = _ports_with_implementations(contract)
    out.add("")
    out.add("")
    out.add("#: Port implementation type name -> the port it implements (contract R1).")
    out.add("PORT_VALUE_TYPENAMES: Final[Mapping[str, str]] = {")
    for port, implementations in ports:
        for implementation in implementations:
            out.add(f'    "{implementation}": "{port}",')
    out.add("}")
    out.add("")
    out.add("")
    out.add("def encode_port_value(typename: str, value: Mapping[str, object]) -> PortValue:")
    out.add('    """Wrap a domain port value in the finite `PortValue` envelope (R2)."""')
    out.add("    if typename not in PORT_VALUE_TYPENAMES:")
    out.add('        raise ValueError(f"unknown port value typename: {typename}")')
    out.add('    return {"__typename": typename, "value": value}')
    out.add("")
    out.add("")
    out.add("def decode_port_value(envelope: PortValue) -> Mapping[str, object]:")
    out.add('    """Unwrap the `PortValue` envelope, rejecting an unknown typename (R2)."""')
    out.add('    typename = envelope["__typename"]')
    out.add("    if not isinstance(typename, str) or typename not in PORT_VALUE_TYPENAMES:")
    out.add('        raise ValueError(f"unknown port value typename: {typename}")')
    out.add('    value = envelope["value"]')
    out.add("    if not isinstance(value, Mapping):")
    out.add('        raise ValueError("port value envelope carries no mapping payload")')
    out.add("    return value")
    if "PortValue" not in used_custom:
        # `PortValue` is used by the two helpers above, so it is always imported.
        out.lines.insert(
            out.lines.index("from .scalars import " + ", ".join(used_custom))
            if used_custom
            else out.lines.index("from .scalars import PortValue"),
            "",
        )
    return EmittedFile("python/leviath_generated/interfaces.py", out.text(), tuple(out.anchors))


def _python_imports_for_operations(contract: Contract) -> List[str]:
    """Composite names the operations module must import from ``.interfaces``."""
    from graphql import is_enum_type

    names = set()
    for operation in contract.operations:
        for selection in _walk(operation.selection):
            if selection.is_leaf and selection.named_type != "PortValue":
                type_ = contract.schema.type_map.get(selection.named_type)
                if type_ is not None and is_enum_type(type_):
                    names.add(selection.named_type)
            else:
                names.add(_composite_name(selection.named_type, contract, python=True))
        for variable in operation.variables:
            base = _unwrap_str(variable.graphql_type)
            if base in PYTHON_CUSTOM_SCALARS:
                names.discard(base)
                continue
            type_ = contract.schema.type_map.get(base)
            if type_ is not None and is_enum_type(type_):
                names.add(base)
    return sorted(names)


def _unwrap_str(graphql_type: str) -> str:
    from graphql import parse_type

    node = parse_type(graphql_type)
    while type(node).__name__ in ("ListTypeNode", "NonNullTypeNode"):
        node = node.type
    return node.name.value


def render_python_operations(contract: Contract) -> EmittedFile:
    out = _Out()
    out.add('"""Generated operation documents and clients. DO NOT EDIT."""')
    out.add("")
    out.add(f"# {BANNER_LINE}")
    out.add(f"# contract fingerprint: {contract.fingerprint}")
    out.add("")
    out.add("from __future__ import annotations")
    out.add("")
    out.add("from typing import Final, Mapping, NotRequired, Optional, Protocol, Sequence, cast")
    imported = _python_imports_for_operations(contract)
    out.add("from typing import TypedDict")
    if imported:
        out.add("")
        out.add("from .interfaces import " + ", ".join(imported))
    used_custom = sorted(
        {
            PYTHON_CUSTOM_SCALARS[_unwrap_str(variable.graphql_type)]
            for operation in contract.operations
            for variable in operation.variables
            if _unwrap_str(variable.graphql_type) in PYTHON_CUSTOM_SCALARS
        }
    )
    if used_custom:
        out.add("from .scalars import " + ", ".join(used_custom))

    out.add("")
    out.add("")
    out.add("#: Operation name -> the exact document sent to the server.")
    out.add("OPERATIONS: Final[Mapping[str, str]] = {")
    for operation in contract.operations:
        out.add(f'    "{operation.name}":')
        out.add(f"        {operation.document!r},")
    out.add("}")
    out.add("")
    out.add("")
    out.add("class OperationExecutor(Protocol):")
    out.add('    """The transport the generated client calls. Handwritten, outside this file."""')
    out.add("")
    out.add(
        "    def execute(self, document: str, variables: Mapping[str, object])"
        " -> Mapping[str, object]: ..."
    )

    for operation in contract.operations:
        out.add("")
        out.add("")
        if operation.variables:
            out.add(f"{operation.name}Variables = TypedDict(", anchor=f"{operation.root_field}.variables")
            out.add(f'    "{operation.name}Variables",')
            out.add("    {")
            for variable in operation.variables:
                annotation = python_annotation(variable.graphql_type, contract)
                if not variable.required:
                    annotation = f"NotRequired[{annotation}]"
                out.add(f'        "{variable.name}": {annotation},')
            out.add("    },")
            out.add(")")
        else:
            out.add(
                f"{operation.name}Variables = TypedDict(",
                anchor=f"{operation.root_field}.variables",
            )
            out.add(f'    "{operation.name}Variables",')
            out.add("    {},")
            out.add(")")

    out.add("")
    out.add("")
    out.add("class WorkflowClient:")
    out.add('    """Typed client for every generated operation."""')
    out.add("")
    out.add("    def __init__(self, executor: OperationExecutor) -> None:")
    out.add("        self._executor = executor")
    for operation in contract.operations:
        out.add("")
        result = _client_result(operation, contract)
        if operation.variables:
            out.add(
                f"    def {snake(operation.root_field)}(self, variables: "
                f"{operation.name}Variables) -> {result}:",
                anchor=operation.root_field,
            )
            out.add(
                f'        payload = self._executor.execute(OPERATIONS["{operation.name}"], dict(variables))'
            )
        else:
            out.add(
                f"    def {snake(operation.root_field)}(self) -> {result}:",
                anchor=operation.root_field,
            )
            out.add(f'        payload = self._executor.execute(OPERATIONS["{operation.name}"], {{}})')
        out.add(f'        return cast({result}, payload["{operation.root_field}"])')
    return EmittedFile("python/leviath_generated/operations.py", out.text(), tuple(out.anchors))


def _client_result(operation: Operation, contract: Contract) -> str:
    return python_annotation(str(_field_type(contract, operation)), contract)


def _field_type(contract: Contract, operation: Operation):
    """The declared type of an operation's root field."""
    roots = []
    if contract.schema.query_type is not None:
        roots.extend(contract.schema.query_type.fields.values())
    if contract.schema.mutation_type is not None:
        roots.extend(contract.schema.mutation_type.fields.values())
    for field in roots:
        if field is not None and str(field.type).replace("!", "") and True:
            pass
    for field in roots:
        if _unwrap(field.type) == operation.selection.named_type and _is_root_field(
            field, operation
        ):
            return field.type
    return operation.selection.graphql_type


def _is_root_field(field, operation: Operation) -> bool:
    return getattr(field, "name", None) == operation.root_field


def render_python_init(contract: Contract) -> EmittedFile:
    out = _Out()
    out.add('"""Generated Python package. DO NOT EDIT."""')
    out.add("")
    out.add(f"# {BANNER_LINE}")
    out.add("")
    out.add("from .interfaces import *  # noqa: F401,F403")
    out.add("from .operations import OPERATIONS, OperationExecutor, WorkflowClient")
    out.add("from .scalars import SCALAR_MAPPINGS, Confidential, PortValue")
    out.add("")
    out.add('__all__ = ["OPERATIONS", "OperationExecutor", "WorkflowClient", "SCALAR_MAPPINGS"]')
    return EmittedFile("python/leviath_generated/__init__.py", out.text())


def render_python_marker(contract: Contract) -> EmittedFile:
    return EmittedFile("python/leviath_generated/py.typed", "")


# ---------------------------------------------------------------------------
# TypeScript.
# ---------------------------------------------------------------------------


def _typescript_enum_lines(out: _Out, contract: Contract) -> None:
    from graphql import is_enum_type

    for name, type_ in contract.schema.type_map.items():
        if name.startswith("__") or not is_enum_type(type_):
            continue
        _assert_identifier(name, "enum type")
        out.add("")
        out.add(
            f"export const {name} = {{ "
            + ", ".join(f'{value}: "{value}"' for value in type_.values)
            + " } as const;",
            anchor=name,
        )
        out.add(f"export type {name} = (typeof {name})[keyof typeof {name}];")
        out.add(f"export const {name}Values: ReadonlyArray<{name}> = Object.values({name});")


def render_typescript_scalars(contract: Contract) -> EmittedFile:
    out = _Out()
    out.add(f"/** Generated scalar mappings. {BANNER_LINE} */")
    out.add("")
    out.add("export type ID = string;")
    out.add("export type String = string;")
    out.add("export type Int = number;")
    out.add("export type Float = number;")
    out.add("export type Boolean = boolean;")
    for name in sorted(PYTHON_CUSTOM_SCALARS):
        if name not in contract.scalars or name == "PortValue":
            continue
        if name == "Confidential":
            continue
        out.add(f"export type {name} = string;")
    out.add("")
    out.add("declare const confidentialBrand: unique symbol;")
    out.add("")
    out.add("/**")
    out.add(" * Opaque sensitive value (contract R6).")
    out.add(" *")
    out.add(" * Nothing here constructs or unwraps a secret: the runtime confirmation gate")
    out.add(" * (GQL-06) supplies the value, authority is the principal plus the exact")
    out.add(" * approved intent, and the brand makes an ad-hoc literal impossible.")
    out.add(" */")
    out.add("export interface Confidential {")
    out.add("  readonly [confidentialBrand]: never;")
    out.add("}")
    out.add("")
    out.add("/** Transport envelope for a domain port value (contract R2). */")
    out.add("export interface PortValue {")
    out.add("  readonly __typename: string;")
    out.add("  readonly value: Readonly<Record<string, unknown>>;")
    out.add("}")
    out.add("")
    out.add("/** GraphQL scalar name -> the TypeScript type the generated stubs use. */")
    out.add("export const SCALAR_MAPPINGS = {")
    for name, row in sorted(scalar_mapping(contract).items()):
        out.add(f'  {name}: "{row["typescript"]}",')
    out.add("} as const;")
    out.add("")
    out.add("export type ScalarName = keyof typeof SCALAR_MAPPINGS;")
    return EmittedFile("typescript/src/scalars.ts", out.text(), tuple(out.anchors))


def render_typescript_interfaces(contract: Contract) -> EmittedFile:
    from graphql import is_enum_type, is_interface_type, is_object_type, is_union_type

    out = _Out()
    out.add(f"/** Generated typed interfaces. {BANNER_LINE} */")
    out.add("")
    used = _typescript_used_scalars(contract)
    out.add("import type { " + ", ".join(used) + ' } from "./scalars";')
    out.add("")
    out.add("export type Maybe<T> = T | null;")
    out.add("export type Exact<T extends { [key: string]: unknown }> = { [K in keyof T]: T[K] };")

    _typescript_enum_lines(out, contract)

    for name, type_ in contract.schema.type_map.items():
        if name.startswith("__") or not is_interface_type(type_):
            continue
        out.add("")
        out.add(f"export interface {name} {{", anchor=name)
        out.add("  /** Human-readable annotation: search and authoring. */")
        for field_name, field in type_.fields.items():
            out.add(
                f"  readonly {field_name}: {typescript_annotation(str(field.type), contract)};",
                anchor=f"{name}.{field_name}",
            )
        out.add("}")

    for name, type_ in contract.schema.type_map.items():
        if name.startswith("__") or name in ROOT_TYPE_NAMES or not is_object_type(type_):
            continue
        extends = "".join(f" extends {i.name}" for i in type_.interfaces)
        out.add("")
        out.add(f"export interface {name}{extends} {{", anchor=name)
        out.add(f'  readonly __typename: "{name}";')
        for field_name, field in type_.fields.items():
            out.add(
                f"  readonly {field_name}: {typescript_annotation(str(field.type), contract)};",
                anchor=f"{name}.{field_name}",
            )
        out.add("}")

    for name, type_ in contract.schema.type_map.items():
        if name.startswith("__") or not is_union_type(type_):
            continue
        out.add("")
        out.add(
            f"export type {name} = "
            + " | ".join(member.name for member in type_.types)
            + ";",
            anchor=name,
        )
    for port, implementations in _ports_with_implementations(contract):
        out.add("")
        out.add(
            f"export type {port}Union = " + " | ".join(implementations) + ";",
            anchor=f"{port}Union",
        )

    out.add("")
    out.add("/** Port implementation type name -> the port it implements (contract R1). */")
    out.add("export const PORT_VALUE_TYPENAMES = {")
    for port, implementations in _ports_with_implementations(contract):
        for implementation in implementations:
            out.add(f'  {implementation}: "{port}",')
    out.add("} as const;")
    out.add("")
    out.add("export type PortValueTypename = keyof typeof PORT_VALUE_TYPENAMES;")
    out.add("")
    out.add("/** Wrap a domain port value in the finite `PortValue` envelope (R2). */")
    out.add("export function encodePortValue(")
    out.add("  typename: PortValueTypename,")
    out.add("  value: Readonly<Record<string, unknown>>,")
    out.add("): PortValue {")
    out.add("  return { __typename: typename, value };")
    out.add("}")
    out.add("")
    out.add("/** Unwrap the `PortValue` envelope, rejecting an unknown typename (R2). */")
    out.add("export function decodePortValue(envelope: PortValue): Readonly<Record<string, unknown>> {")
    out.add("  if (!(envelope.__typename in PORT_VALUE_TYPENAMES)) {")
    out.add("    throw new Error(`unknown port value typename: ${envelope.__typename}`);")
    out.add("  }")
    out.add("  return envelope.value;")
    out.add("}")
    return EmittedFile("typescript/src/interfaces.ts", out.text(), tuple(out.anchors))


def render_typescript_operations(contract: Contract) -> EmittedFile:
    out = _Out()
    out.add(f"/** Generated operation documents and clients. {BANNER_LINE} */")
    out.add("")
    composites, scalars = _typescript_imports_for_operations(contract)
    needs_maybe = any(
        "Maybe<" in typescript_annotation(variable.graphql_type, contract)
        for operation in contract.operations
        for variable in operation.variables
    ) or any(
        "Maybe<" in _ts_client_result(operation, contract)
        for operation in contract.operations
    )
    if needs_maybe:
        composites = sorted(set(composites) | {"Maybe"})
    if composites:
        out.add('import type { ' + ", ".join(composites) + ' } from "./interfaces";')
    if scalars:
        out.add('import type { ' + ", ".join(scalars) + ' } from "./scalars";')
    out.add("")
    out.add("/** Operation name -> the exact document sent to the server. */")
    out.add("export const OPERATIONS = {")
    for operation in contract.operations:
        out.add(f'  {operation.name}:')
        out.add(f"    {json.dumps(operation.document)},")
    out.add("} as const;")
    out.add("")
    out.add("export type OperationName = keyof typeof OPERATIONS;")
    out.add("")

    for operation in contract.operations:
        if operation.variables:
            out.add(
                f"export type {operation.name}Variables = {{",
                anchor=f"{operation.root_field}.variables",
            )
            for variable in operation.variables:
                annotation = typescript_annotation(variable.graphql_type, contract)
                optional = "" if variable.required else "?"
                out.add(f"  readonly {variable.name}{optional}: {annotation};")
            out.add("};")
            out.add("")
        else:
            out.add(
                f"export type {operation.name}Variables = Readonly<Record<string, never>>;",
                anchor=f"{operation.root_field}.variables",
            )
            out.add("")

    out.add("/** The transport the generated client calls. Handwritten, outside this file. */")
    out.add("export interface OperationExecutor {")
    out.add(
        "  execute<TResult>(document: string, variables: Readonly<Record<string, unknown>>)"
        ": TResult;"
    )
    out.add("}")
    out.add("")
    out.add("export class WorkflowClient {")
    out.add("  public constructor(private readonly executor: OperationExecutor) {}")
    for operation in contract.operations:
        result = _ts_client_result(operation, contract)
        out.add("")
        if operation.variables:
            out.add(
                f"  public {operation.root_field}(variables: {operation.name}Variables)"
                f": {result} {{",
                anchor=operation.root_field,
            )
            out.add(
                f"    return this.executor.execute<{result}>(OPERATIONS.{operation.name}, variables);"
            )
        else:
            out.add(
                f"  public {operation.root_field}(): {result} {{",
                anchor=operation.root_field,
            )
            out.add(
                f"    return this.executor.execute<{result}>(OPERATIONS.{operation.name}, {{}});"
            )
        out.add("  }")
    out.add("}")
    return EmittedFile("typescript/src/operations.ts", out.text(), tuple(out.anchors))


def _ts_client_result(operation: Operation, contract: Contract) -> str:
    return typescript_annotation(operation.selection.graphql_type, contract)


def _typescript_imports_for_operations(contract: Contract) -> Tuple[List[str], List[str]]:
    """``(composite names, scalar names)`` the operations module must import.

    Composite names come from ``./interfaces``; scalar aliases come from
    ``./scalars``.  Keeping the two apart is what makes the generated module
    typecheck: a scalar alias is not exported by ``./interfaces``.
    """
    from graphql import is_enum_type

    composites = set()
    scalars = set()
    for operation in contract.operations:
        for selection in _walk(operation.selection):
            type_ = contract.schema.type_map.get(selection.named_type)
            if selection.is_leaf and type_ is not None and is_enum_type(type_):
                composites.add(selection.named_type)
            elif not selection.is_leaf:
                composites.add(_composite_name(selection.named_type, contract, python=False))
        for variable in operation.variables:
            base = _unwrap_str(variable.graphql_type)
            mapped = TYPESCRIPT_SCALARS.get(base)
            if mapped is not None:
                scalars.add(mapped)
                continue
            type_ = contract.schema.type_map.get(base)
            if type_ is not None and is_enum_type(type_):
                composites.add(base)
    return sorted(composites), sorted(scalars)


def render_typescript_index(contract: Contract) -> EmittedFile:
    out = _Out()
    out.add(f"/** Generated TypeScript package. {BANNER_LINE} */")
    out.add("")
    out.add('export * from "./scalars";')
    out.add('export * from "./interfaces";')
    out.add('export * from "./operations";')
    return EmittedFile("typescript/src/index.ts", out.text())


def render_typescript_config(contract: Contract) -> EmittedFile:
    payload = {
        "compilerOptions": {
            "target": "es2020",
            "module": "esnext",
            "moduleResolution": "bundler",
            "lib": ["es2020"],
            "types": [],
            "strict": True,
            "noUncheckedIndexedAccess": True,
            "noImplicitOverride": True,
            "noFallthroughCasesInSwitch": True,
            "forceConsistentCasingInFileNames": True,
            "skipLibCheck": True,
            "noEmit": True,
            "erasableSyntaxOnly": False,
        },
        "include": ["src/**/*.ts"],
    }
    text = json.dumps(payload, indent=2, sort_keys=True) + "\n"
    return EmittedFile("typescript/tsconfig.json", text)


# ---------------------------------------------------------------------------
# Handwritten behaviour: seeded once, never rewritten.
# ---------------------------------------------------------------------------


def render_handwritten_readme(contract: Contract) -> EmittedFile:
    text = f"""# Handwritten behaviour

{BANNER_LINE.replace("generated", "seeded")}

The generator writes these files **once**.  Regeneration never rewrites them, so
your resolver bodies survive every run.  Keep handwritten behaviour here and keep
the generated files untouched.

| path | what lives here |
| --- | --- |
| `python/leviath_handwritten/resolvers.py` | Python resolvers and the operation transport |
| `typescript/resolvers.ts` | TypeScript resolvers and the operation transport |

Contract: `{CONTRACT_SDL_NAME}`, fingerprint `{contract.fingerprint}`.
"""
    return EmittedFile("handwritten/README.md", text, handwritten=True)


def render_handwritten_python(contract: Contract) -> EmittedFile:
    roots = [f"{operation.root_field}" for operation in contract.operations]
    queries = [op.root_field for op in contract.operations if op.kind == "query"]
    mutations = [op.root_field for op in contract.operations if op.kind == "mutation"]
    listed_queries = "\n".join(f'    "{name}",' for name in queries)
    listed_mutations = "\n".join(f'    "{name}",' for name in mutations)
    text = f'''"""Handwritten resolvers. The generator seeds this file and never rewrites it.

Put behaviour here.  The generated package (``leviath_generated``) supplies the
typed shapes, the operation documents and the client; this file supplies the code
that answers them.  Nothing in this file is regenerated, so edits survive.
"""

from __future__ import annotations

from typing import Callable, Mapping

#: Root fields the accepted contract declares, grouped by operation kind.
QUERY_FIELDS: tuple[str, ...] = (
{listed_queries}
)
MUTATION_FIELDS: tuple[str, ...] = (
{listed_mutations}
)


def resolve_workflow(context: Mapping[str, object], info: object, args: Mapping[str, object]) -> Mapping[str, object]:
    """Return the workflow named by ``args["id"]``.

    Replace this body with the real read.  The signature is the only contract the
    generated client needs: a root field name maps to one resolver.
    """
    raise NotImplementedError("handwritten: implement resolve_workflow")


def dispatch_workflow(context: Mapping[str, object], info: object, args: Mapping[str, object]) -> Mapping[str, object]:
    """Dispatch a whole workflow.  Behaviour lives here, never in generated files."""
    raise NotImplementedError("handwritten: implement dispatch_workflow")


def transport(document: str, variables: Mapping[str, object]) -> Mapping[str, object]:
    """The operation transport the generated client calls.

    One function, so the generated client stays free of transport choices.
    """
    raise NotImplementedError("handwritten: implement transport")


#: Root field name -> resolver. Add entries as you implement them.
RESOLVERS: Mapping[str, Callable[..., Mapping[str, object]]] = {{
    "workflow": resolve_workflow,
    "dispatchWorkflow": dispatch_workflow,
}}
'''
    return EmittedFile("handwritten/python/leviath_handwritten/resolvers.py", text, handwritten=True)


def render_handwritten_typescript(contract: Contract) -> EmittedFile:
    listed = "\n".join(f'  "{operation.root_field}",' for operation in contract.operations)
    text = f'''/**
 * Handwritten resolvers. The generator seeds this file and never rewrites it.
 *
 * Put behaviour here.  The generated package supplies the typed shapes, the
 * operation documents and the client; this file supplies the code that answers
 * them.  Nothing in this file is regenerated, so edits survive.
 */

export const ROOT_FIELDS: ReadonlyArray<string> = [
{listed}
];

export function resolveWorkflow(
  _context: Readonly<Record<string, unknown>>,
  _args: Readonly<Record<string, unknown>>,
): Readonly<Record<string, unknown>> {{
  throw new Error("handwritten: implement resolveWorkflow");
}}

export function dispatchWorkflow(
  _context: Readonly<Record<string, unknown>>,
  _args: Readonly<Record<string, unknown>>,
): Readonly<Record<string, unknown>> {{
  throw new Error("handwritten: implement dispatchWorkflow");
}}

/** The operation transport the generated client calls. */
export function transport(
  _document: string,
  _variables: Readonly<Record<string, unknown>>,
): Readonly<Record<string, unknown>> {{
  throw new Error("handwritten: implement transport");
}}

export const resolvers = {{
  workflow: resolveWorkflow,
  dispatchWorkflow,
}};
'''
    return EmittedFile("handwritten/typescript/resolvers.ts", text, handwritten=True)


# ---------------------------------------------------------------------------
# The whole file set.
# ---------------------------------------------------------------------------


def generated_files(contract: Contract) -> List[EmittedFile]:
    """Every generated file, in a fixed order, with no handwritten file."""
    files = [
        render_schema_sdl(contract),
        render_operations_sdl(contract),
        render_python_init(contract),
        render_python_scalars(contract),
        render_python_interfaces(contract),
        render_python_operations(contract),
        render_python_marker(contract),
        render_typescript_config(contract),
        render_typescript_index(contract),
        render_typescript_scalars(contract),
        render_typescript_interfaces(contract),
        render_typescript_operations(contract),
    ]
    return files


def handwritten_files(contract: Contract) -> List[EmittedFile]:
    """The seeded-once file set: created when missing, then never rewritten."""
    return [
        render_handwritten_readme(contract),
        render_handwritten_python(contract),
        render_handwritten_typescript(contract),
    ]


def source_map(contract: Contract, files: Sequence[EmittedFile]) -> str:
    """The source map: every generated symbol -> its contract line."""
    entries: List[dict] = []
    for file in files:
        if file.handwritten or file.path == "contract/schema.graphql":
            continue
        for symbol, line in file.anchors:
            contract_line = contract.contract_lines.get(symbol)
            if contract_line is None:
                continue
            entries.append(
                {
                    "symbol": symbol,
                    "contract_path": f"contract/{CONTRACT_SDL_NAME}",
                    "contract_line": contract_line,
                    "generated_file": file.path,
                    "generated_line": line,
                }
            )
    entries.sort(key=lambda row: (row["symbol"], row["generated_file"], row["generated_line"]))
    payload = {
        "format": SOURCEMAP_FORMAT,
        "contract": {
            "sdl": f"contract/{CONTRACT_SDL_NAME}",
            "fingerprint": contract.fingerprint,
        },
        "scalars": scalar_mapping(contract),
        "entries": entries,
    }
    return json.dumps(payload, indent=2, sort_keys=True) + "\n"


def manifest(contract: Contract, digests: Mapping[str, str], generated_paths: Sequence[str]) -> str:
    """The manifest: the pin, the operation set and every generated digest."""
    payload = {
        "format": MANIFEST_FORMAT,
        "generator": f"leviath_codegen {VERSION}",
        "contract_fingerprint": contract.fingerprint,
        "pinned_fingerprint": contract.pinned_fingerprint,
        "operations": [operation.name for operation in contract.operations],
        "generated_paths": list(generated_paths),
        "handwritten_paths": [file.path for file in handwritten_files(contract)],
        "scalars": sorted(contract.scalars),
        "files": {path: digests[path] for path in sorted(digests)},
    }
    return json.dumps(payload, indent=2, sort_keys=True) + "\n"